const url = require('url');
const REPO = $env.REPO_DIR || '/home/node/repo';
const V = require(REPO + '/automation/security/verify-webhooks.js');
const L = await import(url.pathToFileURL(REPO + '/automation/lib/w07.mjs').href);
const it = $input.first();
const raw = it.binary && it.binary.data ? Buffer.from(it.binary.data.data, 'base64').toString('utf8') : JSON.stringify(it.json.body || {});
const sig = (it.json.headers || {})['x-hub-signature-256'];
if (!V.verifyMetaSignature(raw, sig, $env.META_APP_SECRET)) return [{ json: { valid: false } }];
const body = JSON.parse(raw);
const crypto = require('crypto');
const out = [];
for (const m of L.normaliseInbound(body)) out.push({ json: { valid: true, kind: 'message', msg: m, payload_hash: crypto.createHash('sha256').update(JSON.stringify(m)).digest('hex') } });
for (const e of body.entry || []) for (const ch of e.changes || []) for (const s of (ch.value && ch.value.statuses) || []) out.push({ json: { valid: true, kind: 'status', wamid: s.id, status: s.status, ts: Number(s.timestamp || 0), error: (s.errors && s.errors[0] && (s.errors[0].code + ' ' + (s.errors[0].title || ''))) || null } });
return out.length ? out : [{ json: { valid: true, kind: 'empty' } }];

